<script setup lang="ts">
import { computed, ref } from 'vue'
import type { NavigationTask, PlannerRoute, PlanningStatus, VesselSummary } from '../types/bridge'
import type { CaptainDraftRoute, DraftWaypoint } from '../types/navigation'

const props = defineProps<{ task?: NavigationTask; vessel?: VesselSummary; status: PlanningStatus; plannerRoutes: PlannerRoute[]; selectedRouteIndex?: number; recommendedRouteIndex?: number; plannerError?: string; draft?: CaptainDraftRoute; selectedWaypoint?: DraftWaypoint; editMode: boolean; canCreateDraft: boolean; canUndo: boolean; canRedo: boolean }>()
const emit = defineEmits<{ openTask: []; plan: []; replan: []; selectRoute: [index: number]; createDraft: []; toggleEdit: []; addWaypoint: []; deleteWaypoint: []; insertWaypoint: []; undo: []; redo: []; selectWaypoint: [id: string]; toggleFlag: [field: 'locked' | 'mustPass']; unavailable: [message: string] }>()
const routeOpen = ref(true)
const constraintsOpen = ref(false)
const plannerOpen = ref(true)
const draftOpen = ref(true)
const validationOpen = ref(false)
const draftDistance = computed(() => props.draft ? `${props.draft.distanceNm.toFixed(1)} nm` : 'NOT CALCULATED')
const bestTimeIndex = computed(() => props.plannerRoutes.reduce((best, route, index, all) => route.objectives.time_hours < all[best].objectives.time_hours ? index : best, 0))
const bestDistanceIndex = computed(() => props.plannerRoutes.reduce((best, route, index, all) => route.objectives.distance_km < all[best].objectives.distance_km ? index : best, 0))
const bestRiskIndex = computed(() => props.plannerRoutes.reduce((best, route, index, all) => route.objectives.risk < all[best].objectives.risk ? index : best, 0))
const statusLabel = computed(() => ({ not_started: 'NOT_STARTED', waiting: 'WAITING', planning: 'PLANNING', completed: 'READY', failed: 'FAILED', revalidation_required: 'REVALIDATION', replanning: 'REPLANNING', emergency: 'EMERGENCY' }[props.status]))
function routeMetrics(route?: PlannerRoute): string {
  if (!route) return '尚未生成'
  return `风险 ${route.objectives.risk.toFixed(2)} · ${route.objectives.distance_km.toFixed(1)} km · ${route.objectives.time_hours.toFixed(2)} h`
}
function routeRoles(index: number): string[] {
  if (!props.plannerRoutes.length) return []
  const roles: string[] = []
  if (index === bestRiskIndex.value) roles.push('风险最优')
  if (index === bestTimeIndex.value) roles.push('时间最优')
  if (index === bestDistanceIndex.value) roles.push('路径最优')
  return roles
}
</script>

<template>
  <section class="module-panel planning-center">
    <header class="panel-heading"><div><span class="section-kicker">规划与船长编辑</span><h2>航线规划中心</h2></div><span class="status-chip" :class="`planner-${status}`">{{ statusLabel }}</span></header>
    <div class="process-steps"><span :class="{ done: task }">1 任务</span><span :class="{ done: vessel }">2 船舶</span><span :class="{ done: draft }">3 船长草稿</span><span>4 验证</span></div>
    <div v-if="!task" class="empty-state"><strong>请先创建航行任务</strong><p>设置起点与终点后才能创建人工路线草稿。</p><button class="primary-button" type="button" @click="emit('openTask')">前往任务</button></div>
    <template v-else>
      <section class="planning-section collapsible-section"><header><strong>Route Planning</strong><button class="text-button" type="button" @click="plannerOpen = !plannerOpen">{{ plannerOpen ? '收起' : '展开' }}</button></header><template v-if="plannerOpen"><div class="button-grid three"><button class="secondary-button" type="button" :disabled="!task?.start || !task.destination || status === 'planning' || status === 'replanning'" @click="emit('plan')">{{ status === 'planning' ? 'Planning…' : 'Plan' }}</button><button class="secondary-button" type="button" :disabled="!plannerRoutes.length || status === 'planning' || status === 'replanning'" @click="emit('replan')">Replan</button><button class="secondary-button" type="button" @click="emit('unavailable', '推荐路线和 Captain Draft 仍需经过验证后才能激活')">Clear Draft</button></div><p v-if="plannerError" class="inline-error">{{ plannerError }}</p><p v-else-if="plannerRoutes.length" class="inline-notice">已生成 {{ plannerRoutes.length }} 条 Pareto 候选路线；请选择一条查看。</p><p v-else class="inline-notice">请先设置起点和终点，然后执行 Plan。</p></template></section>
      <section class="planning-section"><header><strong>Route Set</strong><button class="text-button" type="button" @click="routeOpen = !routeOpen">{{ routeOpen ? '收起' : '展开' }}</button></header><div v-if="routeOpen && plannerRoutes.length" class="waypoint-list route-list"><button v-for="(route, index) in plannerRoutes" :key="route.routeId" type="button" class="waypoint-row pareto-route-row" :class="{ selected: selectedRouteIndex === index }" @click="emit('selectRoute', index)"><span class="pareto-route-title">{{ index + 1 }} · {{ route.routeId }}<span v-for="role in routeRoles(index)" :key="role" class="pareto-role">{{ role }}</span></span><small>{{ routeMetrics(route) }}</small></button></div><p v-else-if="routeOpen" class="inline-notice">尚未生成 Pareto 路线。</p></section>
      <section class="planning-section collapsible-section"><header><strong>Captain Draft</strong><button class="text-button" type="button" @click="draftOpen = !draftOpen">{{ draftOpen ? '收起' : '展开' }}</button></header><template v-if="draftOpen"><button v-if="draft" class="secondary-button wide" type="button" @click="emit('toggleEdit')">{{ editMode ? 'Exit Edit Mode' : 'Enter Edit Mode' }}</button><div v-if="!draft" class="draft-create"><p>使用当前任务的 Start → Goal 创建前端 UI-only 草稿。</p><button class="primary-button wide" type="button" :disabled="!canCreateDraft" :title="canCreateDraft ? '创建 CaptainDraftRoute' : '请先设置 Start 和 Goal'" @click="emit('createDraft')">Create Manual Draft</button><small>仅前端草稿，不是 RecommendedRoute、ActiveRoute 或 ValidatedRoute。</small></div><div v-else class="draft-summary"><div><strong>{{ draft.id }}</strong><span>几何距离 {{ draftDistance }}</span></div><dl class="route-status-list"><div><dt>Role</dt><dd>CAPTAIN_DRAFT</dd></div><div><dt>Lifecycle</dt><dd>DRAFT</dd></div><div><dt>Validation</dt><dd>UNCHECKED</dd></div></dl><div v-if="editMode" class="editor-tools"><button type="button" class="secondary-button" @click="emit('addWaypoint')">Add Waypoint</button><button type="button" class="secondary-button" @click="emit('insertWaypoint')" :disabled="!selectedWaypoint">Insert WP</button><button type="button" class="secondary-button" @click="emit('deleteWaypoint')" :disabled="!selectedWaypoint">Delete WP</button><button type="button" class="secondary-button" @click="emit('undo')" :disabled="!canUndo">Undo</button><button type="button" class="secondary-button" @click="emit('redo')" :disabled="!canRedo">Redo</button></div><div class="waypoint-list"><button v-for="wp in draft.waypoints" :key="wp.id" type="button" class="waypoint-row" :class="{ selected: selectedWaypoint?.id === wp.id }" @click="emit('selectWaypoint', wp.id)"><span>{{ wp.sequence }} · {{ wp.name }}</span><small>{{ wp.latitude.toFixed(4) }}°, {{ wp.longitude.toFixed(4) }}° <b v-if="wp.locked">LOCK</b><b v-if="wp.mustPass">MUST PASS</b></small></button></div></div></template></section>
      <section v-if="draft && selectedWaypoint" class="planning-section"><header><strong>Waypoint Constraints</strong><span>{{ selectedWaypoint.name }}</span></header><div class="button-grid"><button class="secondary-button" type="button" @click="emit('toggleFlag', 'locked')">{{ selectedWaypoint.locked ? 'Release Lock' : 'Lock WP' }}</button><button class="secondary-button" type="button" @click="emit('toggleFlag', 'mustPass')">{{ selectedWaypoint.mustPass ? 'Release Must Pass' : 'Must Pass' }}</button></div><dl class="data-list compact"><div><dt>ETA</dt><dd>NOT CALCULATED</dd></div><div><dt>Target STW</dt><dd>NOT CALCULATED</dd></div><div><dt>Notes</dt><dd>{{ selectedWaypoint.notes || 'UNKNOWN' }}</dd></div></dl></section>
      <section class="planning-section collapsible-section"><header><strong>Route Validation</strong><button class="text-button" type="button" @click="validationOpen = !validationOpen">{{ validationOpen ? '收起' : '展开' }}</button></header><template v-if="validationOpen"><div class="button-grid three"><button class="secondary-button" type="button" disabled title="等待 EdgeEvaluator / RouteValidation 后端">Validate Route</button><button class="secondary-button" type="button" disabled title="Route lifecycle backend 未实现">Accept</button><button class="secondary-button" type="button" disabled title="Route lifecycle backend 未实现">Activate</button></div><p class="inline-notice">ValidationStatus 始终保持 UNCHECKED；不会由前端判定 VALID。</p></template></section>
      <section class="planning-section lifecycle-flow"><header><strong>Route Lifecycle</strong><span>DISPLAY ONLY</span></header><div class="lifecycle-steps"><span>RecommendedRoute<br><b>NONE</b></span><i>↓</i><span :class="{ current: draft }">CaptainDraftRoute<br><b>{{ draft ? 'DRAFT' : 'NONE' }}</b></span><i>↓</i><span>CHECKING<br><b>NONE</b></span><i>↓</i><span>VALID / CONDITIONAL / INVALID<br><b>NONE</b></span><i>↓</i><span>ACCEPTED<br><b>NONE</b></span><i>↓</i><span>ACTIVE<br><b>NONE</b></span></div></section>
      <section class="planning-section"><header><strong>Advanced Constraints</strong><button class="text-button" type="button" @click="constraintsOpen = !constraintsOpen">{{ constraintsOpen ? '收起' : '展开' }}</button></header><div v-if="constraintsOpen" class="constraint-grid"><button class="secondary-button" type="button" disabled title="将在后续路线合同/验证能力接入">Lock Segment</button><button class="secondary-button" type="button" disabled title="将在后续路线合同/验证能力接入">Avoid Area</button><button class="secondary-button" type="button" disabled title="将在后续路线合同/验证能力接入">Preferred Corridor</button><button class="secondary-button" type="button" disabled title="将在后续路线合同/验证能力接入">Manual STW</button></div></section>
    </template>
  </section>
</template>
